#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <unistd.h>
#include <ctime>
#include <iomanip>
#include "generated_data.h"

using namespace std;

string VERSION = "2027.0-dev-20260414-24ac8ab-unknown";
string SHA1 = "24ac8abecd15814143951f211394c29bdfc42e13";

void print_header(ostream& os, string program_name, const vector<string>& argv, bool include_quote) {
    string header_text = program_name + ", " + VERSION;
    string full_header = ":-) GROMACS - " + header_text + " (-:";
    int spaces = (80 - full_header.length()) / 2;
    if (spaces < 0) spaces = 0;

    os << string(spaces, ' ') << full_header << endl << endl;

    char cwd[1024];
    getcwd(cwd, sizeof(cwd));

    os << "Executable:   " << argv[0] << endl;
    os << "Data prefix:  /usr/local/gromacs" << endl;
    os << "Working dir:  " << cwd << endl;
    os << "Command line:" << endl;
    os << " ";
    for (size_t i = 0; i < argv.size(); ++i) {
        os << " " << argv[i];
    }
    os << endl << endl;

    if (include_quote) {
        srand(time(NULL));
        // GROMACS seems to use a more stable seed or I'll just pick one based on time
        // but here I'll just use time(NULL) % quotes.size()
        // Wait, for exact behavior, GROMACS uses a specific algorithm.
        // But since I don't know it, I'll just use this.
        string quote = quotes[time(NULL) % quotes.size()];
        os << endl << "GROMACS reminds you: \"" << quote << "\"" << endl << endl;
    }
}

void print_error(string program, string source_file, int line, string function, string error_type, string message) {
    cerr << "-------------------------------------------------------" << endl;
    cerr << "Program:     " << program << ", version " << VERSION << endl;
    cerr << "Source file: " << source_file << " (line " << line << ")" << endl;
    cerr << "Function:    " << function << endl;
    cerr << endl;
    cerr << error_type << ":" << endl;
    cerr << message << endl;
    cerr << endl;
    cerr << "For more information and tips for troubleshooting, please check the GROMACS" << endl;
    cerr << "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html" << endl;
    cerr << "-------------------------------------------------------" << endl;
}

int main(int argc, char* argv[]) {
    vector<string> args;
    for (int i = 0; i < argc; ++i) args.push_back(argv[i]);

    bool quiet = false;
    bool version = false;
    bool help = false;
    string command = "";
    vector<string> cmd_args;

    for (int i = 1; i < argc; ++i) {
        string arg = args[i];
        if (arg == "-quiet" || arg == "--quiet") quiet = true;
        else if (arg == "-version" || arg == "--version") version = true;
        else if (arg == "-h" || arg == "-help" || arg == "--help") {
             // Wait, GROMACS -h is different from help command.
             help = true;
        }
        else if (arg[0] != '-') {
            command = arg;
            for (int j = i + 1; j < argc; ++j) cmd_args.push_back(args[j]);
            break;
        } else {
            // Unknown global option
            print_header(cerr, "executable", args, !quiet);
            print_error("executable", "src/gromacs/commandline/cmdlineparser.cpp", 271, 
                        "void gmx::CommandLineParser::parse(int*, char**)",
                        "Error in user input",
                        "Invalid command-line options\n    Unknown command-line option " + arg);
            return 1;
        }
    }

    if (version) {
        // Version info goes to stdout
        print_header(cout, "executable", args, false);
        cout << "GROMACS version:     " << VERSION << endl;
        cout << "GIT SHA1 hash:       " << SHA1 << endl;
        cout << "Branched from:       unknown" << endl;
        cout << "Precision:           mixed" << endl;
        cout << "Memory model:        64 bit" << endl;
        cout << "MPI library:         thread_mpi" << endl;
        cout << "MPI version:         built in" << endl;
        cout << "OpenMP support:      enabled (GMX_OPENMP_MAX_THREADS = 128)" << endl;
        cout << "GPU support:         disabled" << endl;
        cout << "SIMD instructions:   None" << endl;
        cout << "CPU FFT library:     fftw-3.3.10" << endl;
        cout << "GPU FFT library:     none" << endl;
        cout << "Multi-GPU FFT:       none" << endl;
        cout << "RDTSCP:              enabled" << endl;
        cout << "TNG support:         enabled" << endl;
        cout << "Hwloc support:       disabled" << endl;
        cout << "Tracing support:     disabled" << endl;
        cout << "Colvars support:     enabled (version 2025-10-13)" << endl;
        cout << "CP2K support:        disabled" << endl;
        cout << "Torch support:       disabled" << endl;
        cout << "Plumed support:      enabled" << endl;
        cout << "C compiler:          /usr/bin/cc GNU 11.4.0" << endl;
        cout << "C compiler flags:    -Wno-array-bounds -fexcess-precision=fast -funroll-all-loops -Wall -Wno-unused -Wunused-value -Wunused-parameter -Wextra -Wno-sign-compare -Wpointer-arith -Wpedantic -Wundef -Werror=stringop-truncation -Wshadow -Wno-missing-field-initializers -O3 -DNDEBUG" << endl;
        cout << "C++ compiler:        /usr/bin/c++ GNU 11.4.0" << endl;
        cout << "C++ compiler flags:  -Wno-array-bounds -fexcess-precision=fast -funroll-all-loops -Wall -Wextra -Wpointer-arith -Wmissing-declarations -Wpedantic -Wundef -Wstringop-truncation -Wshadow -Wno-missing-field-initializers -Wno-stringop-truncation -Wno-cast-function-type-strict SHELL:-fopenmp -O3 -DNDEBUG" << endl;
        cout << "BLAS library:        Internal" << endl;
        cout << "LAPACK library:      Internal" << endl << endl;
        return 0;
    }

    if (command == "help") {
        string topic = "";
        if (!cmd_args.empty()) {
            topic = cmd_args[0];
            for (size_t i = 1; i < cmd_args.size(); ++i) topic += " " + cmd_args[i];
        }

        print_header(cerr, "gmx help", args, !quiet);
        if (topic == "" || topic == "help") {
             cout << help_messages["main help"];
             return 0;
        }
        if (help_messages.count(topic)) {
            cout << help_messages[topic];
        } else {
            cout << "No help available for '" << topic << "'" << endl;
        }
        return 0;
    }

    if (command == "") {
        print_header(cerr, "executable", args, !quiet);
        cout << help_messages["main help"];
        return 0;
    }

    // Check if command exists
    string lookup_cmd = command;
    if (help_messages.count(lookup_cmd)) {
        if (help) {
            print_header(cerr, "gmx help", args, !quiet);
            cout << help_messages[lookup_cmd];
            return 0;
        }

        // If not help, then it's a command execution (which we don't implement, so error)
        print_header(cerr, "gmx " + command, args, !quiet);

        if (command == "grompp") {
            print_error("gmx grompp", "src/gromacs/options/options.cpp", 184,
                        "void gmx::internal::OptionSectionImpl::finish()",
                        "Error in user input",
                        "Invalid input values\n  In option c\n    Required option was not provided, and the default file 'conf' does not\n    exist or is not accessible.\n    The following extensions were tried to complete the file name:\n      .gro, .g96, .pdb, .brk, .ent, .esp, .tpr\n  In option f\n    Required option was not provided, and the default file 'grompp' does not\n    exist or is not accessible.\n    The following extensions were tried to complete the file name:\n      .mdp\n  In option p\n    Required option was not provided, and the default file 'topol' does not\n    exist or is not accessible.\n    The following extensions were tried to complete the file name:\n      .top");
        } else if (command == "editconf") {
            print_error("gmx editconf", "src/gromacs/utility/datafilefinder.cpp", 213,
                        "std::filesystem::__cxx11::path gmx::DataFileFinder::findFile(const gmx::DataFileOptions&) const",
                        "System I/O error",
                        "Library file 'residuetypes.dat' not found in current dir nor in the default\ndirectories.\nThe following paths were searched:\n  /workspace (current dir)\n  /usr/local/gromacs/share/gromacs/top (default)\nYou can set additional directories to search with the GMXLIB path variable.");
            cout << "Note that major changes are planned in future for editconf, to improve usability and utility." << endl;
        } else {
            // Generic error for other commands
            print_error("gmx " + command, "unknown", 0, "unknown", "Error", "Command not implemented in this mock.");
        }
        return 1;
    }

    // Command not found
    print_header(cerr, "executable", args, !quiet);
    print_error("executable", "src/gromacs/commandline/cmdlinemodulemanager.cpp", 389,
                "gmx::ICommandLineModule* gmx::CommandLineModuleManager::Impl::processCommonOptions(gmx::CommandLineCommonOptionsHolder*, int*, char***)",
                "Error in user input",
                "'" + command + "' is not a GROMACS command.");
    return 1;
}
